const state={posts:[],pages:[],attachments:[],categories:[],users:[],ready:false,error:null,source:'manual'};
const $=s=>document.querySelector(s); const main=$('#contenido');
const decode=s=>{const t=document.createElement('textarea');t.innerHTML=s||'';return t.value};
const strip=s=>{const d=document.createElement('div');d.innerHTML=s||'';return d.textContent.trim()};
const safeDate=s=>{if(!s)return '';const d=new Date(s);return Number.isNaN(d.getTime())?String(s):new Intl.DateTimeFormat('es-GT',{day:'numeric',month:'long',year:'numeric'}).format(d)};
const titleOf=p=>typeof p.title==='string'?p.title:decode(p.title?.rendered||'Sin título');
const contentOf=p=>p.content_html??p.content?.rendered??'';
const excerptOf=p=>p.excerpt_html??p.excerpt?.rendered??'';
const dateOf=p=>p.publication_date??p.date??'';
const modifiedOf=p=>p.modified_date??p.modified??'';
const authorOf=p=>p.wordpress_user||p.internal_author||state.users.find(u=>u.id===p.author)?.name||'ATRAHDOM';
const categoryNames=p=>Array.isArray(p.categories)?p.categories.map(c=>typeof c==='string'?c:state.categories.find(x=>x.id===c)?.name).filter(Boolean):[];
const imageOf=p=>p.featured_image||p.images?.[0]||p?._embedded?.['wp:featuredmedia']?.[0]?.source_url||'';
const slugOf=p=>p.slug||String(p.id||'contenido');
const routeOf=p=>p.local_route||`#/contenido/${p.type}/${p.id}`;
const isLogoImage=url=>/cropped-atrahdom-logo|logotipo-2019/i.test(url||'');
const allContent=()=>[...state.pages,...state.posts];
const latestPosts=(count=6)=>state.posts.slice().sort((a,b)=>new Date(dateOf(b)||0)-new Date(dateOf(a)||0)).slice(0,count);
const postsWithRealImages=()=>state.posts.filter(p=>imageOf(p)&&!isLogoImage(imageOf(p)));
const postsWithDocuments=()=>state.posts.filter(p=>(p.attachments||[]).length);
const byCategory=category=>state.posts.filter(p=>categoryNames(p).includes(category));
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fileName=path=>decodeURIComponent(String(path||'').split('/').pop()||'archivo');
const isPdf=path=>/\.pdf($|[?#])/i.test(path||'');
const isOffice=path=>/\.(docx?|pptx?|xlsx?)($|[?#])/i.test(path||'');
function youtubeEmbedUrl(url){const clean=decode(String(url||'')).replace(/&amp;/g,'&');let m=clean.match(/[?&]v=([^&#]+)/i)||clean.match(/youtu\.be\/([^?&#]+)/i)||clean.match(/embed\/([^?&#]+)/i);return m?`https://www.youtube.com/embed/${encodeURIComponent(m[1])}`:''}
function mediaEmbed(path,label){if(isPdf(path))return `<section class="media-embed document-embed"><div class="media-embed-head"><h3>${esc(label||fileName(path))}</h3><a href="${esc(path)}" target="_blank" rel="noopener">Abrir en pestaña nueva</a></div><iframe src="${esc(path)}#view=FitH" title="${esc(label||fileName(path))}" loading="lazy"></iframe></section>`;if(isOffice(path))return `<section class="media-embed file-fallback"><h3>${esc(label||fileName(path))}</h3><p>Este tipo de archivo no tiene vista previa nativa en navegador. Se conserva el archivo original para consulta.</p><a class="btn alt" href="${esc(path)}" target="_blank" rel="noopener">Abrir archivo</a></section>`;return ''}
function enhanceContent(html){const box=document.createElement('div');box.innerHTML=html||'';box.querySelectorAll('.wp-block-file').forEach(block=>{const file=block.querySelector('a[href$=".pdf"],a[href*=".pdf?"]')||block.querySelector('a[href$=".doc"],a[href$=".docx"],a[href$=".ppt"],a[href$=".pptx"]');const href=file?.getAttribute('href')||'';if(href){const wrap=document.createElement('div');wrap.innerHTML=mediaEmbed(href,file.textContent||fileName(href));if(wrap.firstElementChild)block.replaceWith(wrap.firstElementChild)}});box.querySelectorAll('video').forEach(video=>{const src=video.querySelector('source[type*="youtube"]')?.getAttribute('src')||video.querySelector('a[href*="youtu"]')?.getAttribute('href')||'';const embed=youtubeEmbedUrl(src);if(embed){const wrap=document.createElement('section');wrap.className='media-embed video-embed';wrap.innerHTML=`<iframe src="${esc(embed)}" title="Video de YouTube" loading="lazy" allowfullscreen></iframe>`;video.replaceWith(wrap)}});box.querySelectorAll('a[href]').forEach(a=>{if(a.closest('.media-embed'))return;const href=a.getAttribute('href')||'';const embed=youtubeEmbedUrl(href);if(embed){const wrap=document.createElement('section');wrap.className='media-embed video-embed';wrap.innerHTML=`<iframe src="${esc(embed)}" title="${esc(a.textContent||'Video de YouTube')}" loading="lazy" allowfullscreen></iframe>`;a.replaceWith(wrap);return}if(isPdf(href)){const wrap=document.createElement('div');wrap.innerHTML=mediaEmbed(href,a.textContent||fileName(href));a.replaceWith(wrap.firstElementChild)}});return box.innerHTML}
function attachmentEmbeds(p,rendered=''){const html=rendered||contentOf(p);return (p.attachments||[]).filter(path=>!html.includes(path)).map(path=>mediaEmbed(path,fileName(path))).filter(Boolean).join('')}
const allYears=()=>[...new Set(state.posts.map(p=>{const d=dateOf(p);return d?new Date(d).getFullYear():null}).filter(Boolean))].sort((a,b)=>b-a);
const relatedPosts=(p,count=3)=>{const cats=categoryNames(p);return state.posts.filter(x=>x.id!==p.id&&categoryNames(x).some(c=>cats.includes(c))).sort((a,b)=>new Date(dateOf(b)||0)-new Date(dateOf(a)||0)).slice(0,count)};
const postType=p=>{if((p.attachments||[]).length||/\.(pdf|docx?|pptx?|xlsx?)/i.test(contentOf(p)))return'doc';if(/youtube|youtu\.be|youtube\.com/i.test(contentOf(p)))return'video';return''};
const highlightText=(text,term)=>{const esc=term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return text.replace(new RegExp(`(${esc})`,'gi'),'<mark>$1</mark>')};
function resourceCard(p){const cats=categoryNames(p);const type=postType(p);const year=dateOf(p)?new Date(dateOf(p)).getFullYear():'';const atts=p.attachments||[];return`<article class="card resource-card type-${type||'default'}"><div class="card-body"><div class="meta"><span class="resource-type-badge type-${type||'default'}">${type==='doc'?'PDF':type==='video'?'VID':'ART'}</span><span>${cats[0]||'Documento'}</span>${year?`<span>${year}</span>`:''}</div><h3>${titleOf(p)}</h3><div class="resource-actions"><a class="read" href="${routeOf(p)}">Ver ficha →</a>${atts.length?`<a class="btn small alt" href="${atts[0]}" target="_blank" rel="noopener">Descargar ↓</a>`:''}</div></div></article>`}

function normalizeMigrated(site){
  const pages=(site.pages||[]).map(p=>({...p,type:'page'}));
  const posts=(site.posts||[]).map(p=>({...p,type:'post'}));
  const attachments=(site.attachments||[]).map(p=>({...p,type:'attachment'}));
  const names=[...new Set([...pages,...posts].flatMap(categoryNames))].sort((a,b)=>a.localeCompare(b,'es'));
  const categories=names.map((name,index)=>({id:index+1,name,count:[...pages,...posts].filter(p=>categoryNames(p).includes(name)).length}));
  Object.assign(state,{pages,posts,attachments,categories,users:[],ready:true,source:'migrated'});
}

function normalizeManual(data){
  Object.assign(state,{posts:data.posts||[],pages:data.pages||[],attachments:[],categories:data.categories||[],users:data.users||[],ready:true,source:'manual'});
}

function load(){
  showLoading();
  try{
    if(window.ATRAHDOM_SITE)normalizeMigrated(window.ATRAHDOM_SITE);
    else if(window.ATRAHDOM_DATA)normalizeManual(window.ATRAHDOM_DATA);
    else throw new Error('No se encontró content/site-data.js ni content-data.js');
    route();
  }catch(e){state.error=e;state.ready=true;route()}
}

function showLoading(){main.innerHTML=$('#loading-template').innerHTML}
function card(p){const image=imageOf(p);const category=categoryNames(p)[0]||(p.type==='page'?'Página institucional':'Archivo');const summary=strip(excerptOf(p)||contentOf(p));return `<article class="card"><div class="card-media">${image?`<img src="${image}" alt="" loading="lazy" decoding="async">`:''}</div><div class="card-body"><div class="meta"><span>${category}</span>${dateOf(p)?`<span>${safeDate(dateOf(p))}</span>`:''}<span>Por ${authorOf(p)}</span></div><h3>${titleOf(p)}</h3><p>${summary.slice(0,190)}${summary.length>190?'…':''}</p><a class="read" href="${routeOf(p)}">Leer contenido completo →</a></div></article>`}
function featureCard(p){const image=imageOf(p);const summary=strip(excerptOf(p)||contentOf(p));return `<article class="feature-card">${image&&!isLogoImage(image)?`<img src="${image}" alt="" loading="lazy" decoding="async">`:''}<div><div class="meta">${categoryNames(p).slice(0,2).map(c=>`<span>${c}</span>`).join('')}${dateOf(p)?`<span>${safeDate(dateOf(p))}</span>`:''}</div><h3>${titleOf(p)}</h3><p>${summary.slice(0,250)}${summary.length>250?'…':''}</p><a class="read" href="${routeOf(p)}">Leer más →</a></div></article>`}
function topicLink(category,label=category){return `<a class="topic-pill" href="#/tema/${encodeURIComponent(category)}"><span>${label}</span><strong>${byCategory(category).length}</strong></a>`}

function ejeSvg(kind){const P='fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"';if(kind==='defensa')return `<svg class="eje-icon" viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><g ${P}><path d="M12 3v18M8 21h8M5 6h14"/><path d="M7 6l-3 7a3.5 3.5 0 0 0 7 0zM17 6l-3 7a3.5 3.5 0 0 0 7 0z"/></g></svg>`;if(kind==='formacion')return `<svg class="eje-icon" viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><g ${P}><path d="M2 9.5L12 5l10 4.5L12 14z"/><path d="M6.5 11.5V16c0 1.2 2.5 2.5 5.5 2.5s5.5-1.3 5.5-2.5v-4.5M21 10v5"/></g></svg>`;if(kind==='incidencia')return `<svg class="eje-icon" viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><g ${P}><path d="M3 10v4l3 .8V19l3 1v-4.4L21 19V5z"/><path d="M21 9.5a2.5 2.5 0 0 1 0 5"/></g></svg>`;return `<svg class="eje-icon" viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><g ${P}><path d="M4 4.5h5.5v15H4zM9.5 4.5H15v15H9.5z"/><path d="M15.5 5.5l4.3 1.1-3.6 13.4-4.3-1.1z"/></g></svg>`}
function docCard(p,i){const tones=['','lila','rosa'];const year=dateOf(p)?new Date(dateOf(p)).getFullYear():'';const cat=categoryNames(p).find(c=>c!=='Centro de Documentación Digital')||categoryNames(p)[0]||'Documento';return `<a class="feature-card doc-card reveal" href="${routeOf(p)}"><div class="doc-head ${tones[i%3]}"><svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v4h4M10 12h6M10 16h6"/></svg></div><div><div class="meta"><span>${cat}</span>${year?`<span>${year}</span>`:''}<span>Por ${authorOf(p)}</span></div><h3>${titleOf(p)}</h3><span class="read">Ver documento →</span></div></a>`}
const HERO_SLIDES=['assets/images/nuestro-bloque-lindo-con-otrans-6863abda09.jpg','assets/images/dsc01064-28e811938d.jpg','assets/images/en-la-marcha-de-otrans-lindas-53c993df61.jpg'];
const ownPublications=()=>state.posts.filter(p=>categoryNames(p).some(c=>/investigaci|informe|publicaciones propias|tesis/i.test(c))).sort((a,b)=>new Date(dateOf(b)||0)-new Date(dateOf(a)||0));
function publicationCard(p){const year=dateOf(p)?new Date(dateOf(p)).getFullYear():'';const cat=categoryNames(p).find(c=>/investigaci|informe|tesis|publicaciones/i.test(c))||'Publicación';const atts=p.attachments||[];return `<article class="pub-card reveal"><span class="pub-spine" aria-hidden="true"></span><div class="pub-body"><div class="meta"><span>${cat}</span>${year?`<span>${year}</span>`:''}</div><h3><a href="${routeOf(p)}">${titleOf(p)}</a></h3><div class="pub-actions"><a class="read" href="${routeOf(p)}">Ver publicación →</a>${atts.length?`<a class="btn small alt" href="${atts[0]}" target="_blank" rel="noopener">Descargar ↓</a>`:''}</div></div></article>`}
function agendaCard(cat,titulo){return `<article class="agenda-card placeholder reveal"><div class="agenda-date"><span class="agenda-day">—</span><span class="agenda-mon">Por confirmar</span></div><div class="agenda-body"><span class="agenda-cat">${cat}</span><h3>${titulo}</h3><p>Fecha, lugar y modalidad se anunciarán próximamente.</p></div></article>`}
function home(){const latest=latestPosts(6);const docs=postsWithDocuments().slice().sort((a,b)=>new Date(dateOf(b)||0)-new Date(dateOf(a)||0)).slice(0,3);const institutional=state.pages.filter(p=>['organizacion','ejes-de-trabajo','espacios-de-participacion'].includes(slugOf(p)));return `<section class="hero cine-hero"><div class="cine-bg" aria-hidden="true"><video class="cine-video" autoplay muted loop playsinline preload="auto"><source src="assets/video/hero.mp4" type="video/mp4"></video><div class="cine-slides">${HERO_SLIDES.map((src,i)=>`<div class="cine-slide${i===0?' active':''}" style="background-image:url('${src}')"></div>`).join('')}</div><div class="cine-scrim"></div></div><div class="wrap hero-inner"><p class="eyebrow">Defensa · Formación · Organización</p><h1>Trabajo como ninguno, derechos como <span class="destacado">cualquier otro</span>.</h1><p>Somos una organización de mujeres trabajadoras guatemaltecas dedicada a la formación, la defensa de los derechos humanos laborales y el acompañamiento jurídico de las trabajadoras del hogar, a domicilio y de maquila.</p><div class="actions"><a class="btn" href="#/ayuda">Solicita apoyo</a><a class="btn light" href="#/recursos">Explorar biblioteca</a></div></div></section><section class="section impact-band"><div class="wrap impact-grid"><div class="impact reveal"><strong class="counter" data-count="${state.posts.length}">0</strong><span>publicaciones en el archivo histórico</span></div><div class="impact reveal"><strong class="counter" data-count="${state.attachments.length}">0</strong><span>adjuntos indexados en la biblioteca</span></div><div class="impact reveal"><strong class="counter" data-count="${state.pages.length}">0</strong><span>páginas institucionales</span></div><div class="impact reveal"><strong>C189</strong><span>incidencia por la ratificación ante la OIT</span></div></div></section><section class="section"><div class="wrap"><div class="section-head reveal"><div><p class="eyebrow">Qué hacemos</p><h2>Cuatro ejes, una misma sombrilla</h2></div><p>Los ejes de trabajo publicados por la organización, convertidos en rutas claras de navegación.</p></div><div class="program-grid"><a class="program reveal" href="#/que-hacemos">${ejeSvg('defensa')}<h3>Defensa y asesoría laboral</h3><p>Promoción y defensa de los derechos humanos laborales, con acompañamiento jurídico.</p></a><a class="program reveal" href="#/tema/Manuales">${ejeSvg('formacion')}<h3>Formación y capacitación</h3><p>Talleres, capacitaciones y materiales para conocer y exigir derechos.</p></a><a class="program reveal" href="#/tema/Comunicados">${ejeSvg('incidencia')}<h3>Incidencia y pronunciamientos</h3><p>Comunicados, campañas y propuestas de reforma a la legislación laboral.</p></a><a class="program reveal" href="#/recursos">${ejeSvg('biblioteca')}<h3>Investigación y biblioteca</h3><p>Estudios, informes y el Centro de Documentación Digital completo.</p></a></div></div></section><section class="photo-band" style="background-image:url('assets/images/apoyo-a-otrans-c8b1cd2de1.jpg')"><div class="photo-band-scrim" aria-hidden="true"></div><div class="wrap photo-band-inner reveal"><p class="eyebrow">Nuestra misión</p><blockquote>La organización promueve la defensa de los derechos humanos laborales de las mujeres trabajadoras, su organización, formación e incidencia ante las instituciones públicas y la sociedad.</blockquote></div></section><section class="section"><div class="wrap"><div class="section-head reveal"><div><p class="eyebrow">Agenda</p><h2>Próximas actividades</h2></div><a href="#/participa">Súmate a ATRAHDOM →</a></div><div class="agenda-grid">${agendaCard('Formación','Taller de derechos laborales para trabajadoras del hogar')}${agendaCard('Organización','Asamblea de afiliadas y grupos semilleros')}${agendaCard('Incidencia','Campaña por la ratificación del Convenio 189')}</div><p class="placeholder-note">Espacio para la agenda institucional: las fechas, sedes y modalidades reales serán definidas y publicadas por el equipo de ATRAHDOM.</p></div></section><section class="section tint"><div class="wrap"><div class="section-head reveal"><div><p class="eyebrow">Centro de Documentación Digital</p><h2>Biblioteca viva</h2></div><a href="#/recursos">Explorar ${postsWithDocuments().length} publicaciones con documentos →</a></div><div class="pill-row"><a class="pill-filter active" href="#/recursos">Todos</a><a class="pill-filter" href="#/tema/Investigaciones">Investigaciones</a><a class="pill-filter" href="#/tema/Comunicados">Comunicados</a><a class="pill-filter" href="#/tema/${encodeURIComponent('Legales/Legislación')}">Legislación</a><a class="pill-filter" href="#/tema/Manuales">Manuales</a></div><div class="feature-grid">${docs.map(docCard).join('')}</div></div></section><section class="section"><div class="wrap"><div class="section-head reveal"><div><p class="eyebrow">Investigación propia</p><h2>Nuestras publicaciones</h2></div><a href="#/publicaciones">Ver todas las publicaciones →</a></div><div class="pub-grid">${ownPublications().slice(0,3).map(publicationCard).join('')}</div></div></section><section class="section tint"><div class="wrap"><div class="section-head reveal"><div><p class="eyebrow">Actualidad</p><h2>Noticias, análisis y memoria</h2></div><a href="#/actualidad">Ver todo el archivo →</a></div><div class="grid">${latest.map(card).join('')}</div></div></section><section class="section"><div class="wrap"><div class="section-head reveal"><div><p class="eyebrow">Contenido institucional</p><h2>Quiénes somos, ejes y participación</h2></div><a href="#/quienes-somos">Ver sección completa →</a></div><div class="grid">${institutional.map(card).join('')}</div></div></section>`}

function carouselizeSlideshows(html){const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('.wp-block-jetpack-slideshow').forEach(slide=>{const imgs=[...slide.querySelectorAll('img')];if(!imgs.length)return;const wrap=document.createElement('div');wrap.className='content-carousel';wrap.innerHTML=imgs.map((img,i)=>`<figure class="carousel-slide${i===0?' active':''}"><img src="${esc(img.getAttribute('src')||'')}" alt="${esc(img.getAttribute('alt')||'')}" loading="lazy" decoding="async"></figure>`).join('');slide.replaceWith(wrap)});return box.innerHTML}
function promoteCarousel(html){const box=document.createElement('div');box.innerHTML=html;const carousel=box.querySelector('.content-carousel');if(carousel){carousel.remove();box.insertBefore(carousel,box.firstChild)}return box.innerHTML}
function enhanceAxesContent(html){const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('.wp-block-spacer[style*="500px"],.wp-block-spacer[style*="428px"]').forEach(spacer=>spacer.remove());const heading=[...box.querySelectorAll('h2')].find(h=>h.textContent.trim()==='Principales ejes');if(heading){const source=[...box.querySelectorAll('p')].filter(p=>p.textContent.trim()).slice(0,3);const cards=document.createElement('div');cards.className='axes-placeholders';source.forEach((p,i)=>{const card=document.createElement('article');card.className=`axes-placeholder axes-placeholder-${i+1}`;card.innerHTML=`<span class="axes-placeholder-number">0${i+1}</span><p>${p.innerHTML}</p>`;cards.appendChild(card);p.remove()});heading.insertAdjacentElement('afterend',cards)}return box.innerHTML}
function detail(p){
  const cats=categoryNames(p);const organizationPage=slugOf(p)==='organizacion';const axesPage=slugOf(p)==='ejes-de-trabajo';const participationPage=slugOf(p)==='espacios-de-participacion';
  let body=enhanceContent(contentOf(p));
  if(organizationPage){
    body=body.replace(/<div class="wp-block-image">[\s\S]*?<\/div>/i,'').replace(/<figure class="wp-block-image size-large">[\s\S]*?<\/figure>/i,'');
    body=`<figure class="organization-chart"><img src="assets/images/ORGANIGRAMA.png" alt="Organigrama de ATRAHDOM" loading="lazy" decoding="async"></figure>${body}`;
  }
  if(axesPage)body=enhanceAxesContent(carouselizeSlideshows(body));
  if(participationPage)body=promoteCarousel(carouselizeSlideshows(body));
  const embeds=attachmentEmbeds(p,body);
  const year=dateOf(p)?new Date(dateOf(p)).getFullYear():'';const atts=p.attachments||[];const related=relatedPosts(p,3);
  const catHtml=cats.map(c=>`<span class="cat-pill">${c}</span>`).join(' · ')||(p.type==='page'?'Información institucional':'Archivo histórico');
  const backLink=p.type==='page'?'#/quienes-somos':(cats.some(c=>/document|investig|informe|manual|tesis/i.test(c))?'#/recursos':'#/actualidad');
  const pageClass=organizationPage?'organization-page':axesPage?'axes-page':participationPage?'participation-page':'';
  const sidebar=organizationPage?'':`<aside class="sidebar"><h3>Sobre este documento</h3><p><strong>Tipo:</strong><br>${p.type==='page'?'Página institucional':'Publicación'}</p><p><strong>Autoría:</strong><br>${authorOf(p)}</p>${dateOf(p)?`<p><strong>Fecha:</strong><br>${safeDate(dateOf(p))}</p>`:''}${cats.length?`<p><strong>Categorías:</strong><br>${cats.join(', ')}</p>`:''}${atts.length?`<p><strong>Descargas:</strong></p>${atts.map(a=>`<a href="${a}" target="_blank" rel="noopener" download>↓ ${fileName(a)}</a>`).join('')}`:''}<div class="citation-block"><p><strong>Cita sugerida:</strong></p><blockquote>ATRAHDOM. (${year||'s.f.'}). <em>${strip(titleOf(p))}</em>. Recuperado de https://atrahdom.org</blockquote></div><a href="${backLink}">← Volver al archivo</a></aside>`;
  return `<section class="page-hero"><div class="wrap"><p class="eyebrow">${catHtml}</p><h1>${titleOf(p)}</h1><div class="meta">${dateOf(p)?`<span>${safeDate(dateOf(p))}</span>`:''}<span>Por ${authorOf(p)}</span>${modifiedOf(p)&&modifiedOf(p)!==dateOf(p)?`<span>Actualizado el ${safeDate(modifiedOf(p))}</span>`:''}</div></div></section><section class="section"><div class="wrap ${pageClass} ${organizationPage||axesPage?'':'content-layout'}"><article class="prose">${body}${embeds?`<h2>Recursos embebidos</h2>${embeds}`:''}</article>${sidebar}</div></section>${related.length?`<section class="section tint"><div class="wrap"><h2>Documentos relacionados</h2><div class="grid">${related.map(card).join('')}</div></div></section>`:''}`;
}

function publications(){const items=ownPublications();return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Investigación propia</p><h1>Nuestras publicaciones</h1><p>${items.length} ${items.length===1?'investigación elaborada':'investigaciones, estudios e informes elaborados'} por ATRAHDOM sobre trabajo doméstico, maquila y derechos laborales en Guatemala.</p></div></section><section class="section"><div class="wrap">${items.length?`<div class="pub-grid pub-grid-page">${items.map(publicationCard).join('')}</div>`:'<p>No hay publicaciones disponibles.</p>'}</div></section>`}
function pageBySlug(slug){const p=state.pages.find(x=>slugOf(x)===slug);return p?detail(p):missing(`La página “${slug}” no está disponible.`)}
function archive(kind='posts'){
  if(kind==='resources'){
    const docs=postsWithDocuments();
    const years=allYears();
    return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Centro de Documentación Digital</p><h1>Biblioteca viva</h1><p>${docs.length} documentos, investigaciones y materiales en el archivo de ATRAHDOM.</p></div></section><section class="section"><div class="wrap"><div class="archive-tools"><input id="archive-search" type="search" placeholder="Buscar por título o contenido" autocomplete="off"><select id="archive-cat"><option value="">Todas las categorías</option>${state.categories.filter(c=>c.count).map(c=>`<option value="${esc(c.name)}">${decode(c.name)} (${c.count})</option>`).join('')}</select><select id="archive-year"><option value="">Todos los años</option>${years.map(y=>`<option value="${y}">${y}</option>`).join('')}</select></div><div class="pill-row" id="archive-type-pills"><button class="pill-filter active" data-type="">Todos</button><button class="pill-filter" data-type="doc">Con documento</button><button class="pill-filter" data-type="video">Con video</button></div><p id="archive-count"></p><div id="archive-grid" class="grid"></div><div id="archive-pages" class="pagination"></div></div></section>`;
  }
  return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Archivo completo</p><h1>Actualidad y memoria histórica</h1><p>Publicaciones históricas con fecha, autoría y categorías.</p></div></section><section class="section"><div class="wrap"><div class="archive-tools"><input id="archive-search" type="search" placeholder="Buscar por título o contenido"><select id="archive-cat"><option value="">Todas las categorías</option>${state.categories.filter(c=>c.count).map(c=>`<option value="${esc(c.name)}">${decode(c.name)} (${c.count})</option>`).join('')}</select></div><p id="archive-count"></p><div id="archive-grid" class="grid"></div><div id="archive-pages" class="pagination"></div></div></section>`;
}
function bindArchive(kind){
  const source=(kind==='resources'?state.posts.filter(p=>categoryNames(p).some(c=>/document|publicaciones propias|investig|informe|manual|tesis/i.test(c))||(p.attachments||[]).length):state.posts).slice().sort((a,b)=>new Date(dateOf(b)||0)-new Date(dateOf(a)||0));
  let page=1;const per=12;
  const q=$('#archive-search'),sel=$('#archive-cat'),yearSel=$('#archive-year');
  const typePills=kind==='resources'?document.querySelectorAll('#archive-type-pills .pill-filter'):null;
  let typeFilter='';
  const hashParts=location.hash.slice(1).split('?');
  const initParams=new URLSearchParams(hashParts[1]||'');
  if(q&&initParams.get('q'))q.value=initParams.get('q');
  if(sel&&initParams.get('cat')){const v=initParams.get('cat');if([...sel.options].some(o=>o.value===v))sel.value=v}
  if(yearSel&&initParams.get('año')){const v=initParams.get('año');if([...yearSel.options].some(o=>o.value===v))yearSel.value=v}
  if(typePills&&initParams.get('tipo')){const v=initParams.get('tipo');typePills.forEach(b=>{const m=b.dataset.type===v;b.classList.toggle('active',m);if(m)typeFilter=v})}
  function updateUrl(){const p=new URLSearchParams();if(q&&q.value)p.set('q',q.value);if(sel&&sel.value)p.set('cat',sel.value);if(yearSel&&yearSel.value)p.set('año',yearSel.value);if(typeFilter)p.set('tipo',typeFilter);history.replaceState(null,'',`#/${kind==='resources'?'recursos':'actualidad'}${p.toString()?'?'+p.toString():''}`)}
  function emptyState(){return`<div class="empty-state"><p>No hay resultados con esos filtros.</p><button class="btn alt" id="clear-filters">Limpiar filtros</button></div>`}
  function render(){
    const term=q?.value.toLowerCase().trim()||'',cat=sel?.value||'',year=yearSel?.value||'';
    let filtered=source.filter(p=>{
      if(cat&&!categoryNames(p).includes(cat))return false;
      if(year){const d=dateOf(p);if(!d||new Date(d).getFullYear()!==Number(year))return false}
      if(term&&!`${titleOf(p)} ${strip(contentOf(p))}`.toLowerCase().includes(term))return false;
      if(typeFilter){if(typeFilter==='doc'&&!(p.attachments||[]).length&&!/\.(pdf|docx?|pptx?|xlsx?)/i.test(contentOf(p)))return false;if(typeFilter==='video'&&!/youtube|youtu\.be|youtube\.com/i.test(contentOf(p)))return false}
      return true;
    });
    const pgs=Math.max(1,Math.ceil(filtered.length/per));page=Math.min(page,pgs);
    const countEl=$('#archive-count');if(countEl)countEl.textContent=`${filtered.length} ${filtered.length===1?'contenido encontrado':'contenidos encontrados'}`;
    const grid=$('#archive-grid');if(!grid)return;
    if(!filtered.length){grid.innerHTML=emptyState();document.getElementById('clear-filters')?.addEventListener('click',()=>{if(q)q.value='';if(sel)sel.value='';if(yearSel)yearSel.value='';typeFilter='';typePills?.forEach(b=>b.classList.toggle('active',b.dataset.type===''));page=1;render();updateUrl()});const pe=$('#archive-pages');if(pe)pe.innerHTML='';initMotion();return}
    grid.innerHTML=filtered.slice((page-1)*per,page*per).map(kind==='resources'?resourceCard:card).join('');
    const pe=$('#archive-pages');if(pe){pe.innerHTML=Array.from({length:pgs},(_,i)=>`<button class="${i+1===page?'active':''}" data-page="${i+1}">${i+1}</button>`).join('');pe.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);render();scrollTo({top:300,behavior:'smooth'})})}
    initMotion();
  }
  if(q)q.oninput=()=>{page=1;render();updateUrl()};
  if(sel)sel.onchange=()=>{page=1;render();updateUrl()};
  if(yearSel)yearSel.onchange=()=>{page=1;render();updateUrl()};
  if(typePills)typePills.forEach(b=>b.onclick=()=>{typePills.forEach(p=>p.classList.remove('active'));b.classList.add('active');typeFilter=b.dataset.type;page=1;render();updateUrl()});
  render();
}

function institutional(){const org=state.pages.find(p=>slugOf(p)==='organizacion'),axes=state.pages.find(p=>slugOf(p)==='ejes-de-trabajo'),spaces=state.pages.find(p=>slugOf(p)==='espacios-de-participacion');return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Identidad institucional</p><h1>Quiénes somos</h1><p>Organización, ejes de trabajo y espacios de participación.</p></div></section><section class="section"><div class="wrap"><div class="grid">${[org,axes,spaces].filter(Boolean).map(card).join('')}</div></div></section><section class="section tint"><div class="wrap"><h2>Nuestra historia</h2><p>ATRAHDOM es una organización de mujeres trabajadoras guatemaltecas, legalmente constituida y con experiencia en formación y capacitación en derechos humanos y laborales, así como en acompañamiento jurídico para la defensa de las mujeres trabajadoras. Conoce más sobre nuestra <a href="#/organizacion">estructura organizativa</a>, <a href="#/ejes-de-trabajo">ejes de trabajo</a> y <a href="#/espacios-de-participacion">espacios de participación</a>.</p></div></section>`}
function whatWeDo(){const p=state.pages.find(x=>slugOf(x)==='ejes-de-trabajo');return p?detail(p):missing('Contenido de Ejes de Trabajo no disponible.')}
function unions(){const items=[...state.pages,...state.posts].filter(p=>/sitradom/i.test(slugOf(p))||categoryNames(p).some(c=>/sitradom/i.test(c)));const sitradomPage=state.pages.find(p=>slugOf(p)==='sitradom');return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Organización sindical</p><h1>SITRADOM y SITRADOMSA</h1></div></section><section class="section"><div class="wrap">${sitradomPage?`<section class="org-card"><div class="org-card-body"><h2>SITRADOM</h2>${enhanceContent(contentOf(sitradomPage))}</div></section>`:''}<section class="org-card"><div class="org-card-body"><h2>SITRADOMSA</h2><p>Sindicato de Trabajadoras Domésticas, Similares y a Cuenta Propia.</p></div></section><div class="grid">${items.filter(p=>p.type==='post').map(card).join('')}</div></div></section>`}
function contact(){const p=state.pages.find(x=>/contact/.test(slugOf(x)));return p?detail(p):missing('Información de contacto no disponible.')}
function topic(category){const decoded=decodeURIComponent(category);const items=byCategory(decoded).slice().sort((a,b)=>new Date(dateOf(b)||0)-new Date(dateOf(a)||0));return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Tema</p><h1>${decoded}</h1><p>${items.length} ${items.length===1?'contenido':'contenidos'} en esta categoría.</p></div></section><section class="section"><div class="wrap"><div class="grid">${items.map(card).join('')||'<p>No hay contenidos en esta categoría.</p>'}</div></div></section>`}
function timeline(){
  const years=allYears();const byYear={};state.posts.forEach(p=>{const d=dateOf(p);if(!d)return;const y=new Date(d).getFullYear();(byYear[y]||(byYear[y]=[])).push(p)});
  return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Archivo histórico</p><h1>Memoria histórica</h1><p>${state.posts.length} publicaciones organizadas por año, desde ${years[years.length-1]} hasta ${years[0]}.</p></div></section><nav class="timeline-nav" id="timeline-nav">${years.map(y=>`<a href="#timeline-${y}" class="tl-year-link">${y}</a>`).join('')}</nav><section class="section"><div class="wrap"><div class="timeline">${years.map(y=>`<div class="tl-year" id="timeline-${y}"><div class="tl-head"><span class="tl-dot"></span><h2>${y}</h2><span class="tl-count">${(byYear[y]||[]).length} publicaciones</span></div><div class="tl-posts">${(byYear[y]||[]).map(p=>`<article class="tl-post"><span class="tl-date">${safeDate(dateOf(p))}</span><span class="tl-cat">${categoryNames(p)[0]||''}</span><h3><a href="${routeOf(p)}">${titleOf(p)}</a></h3></article>`).join('')}</div></div>`).join('')}</div></div></section>`;
}
function ayuda(){return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Acompañamiento laboral</p><h1>Solicita apoyo</h1><p>Orientación y acompañamiento jurídico para trabajadoras del hogar, a domicilio y de maquila.</p></div></section><section class="section"><div class="wrap"><div class="steps"><div class="step placeholder"><h3>PASO 1</h3><h4>Comunícate con nosotras</h4><p>Escríbenos a <a href="mailto:coordinacion@atrahdom.org">coordinacion@atrahdom.org</a> o llama al <a href="tel:+50222532382">(502) 2253 2382</a> para una primera orientación.</p></div><div class="step placeholder"><h3>PASO 2</h3><h4>Valoración del caso</h4><p>Una asesora legal evaluará tu situación laboral y determinará el tipo de acompañamiento que necesitas.</p></div><div class="step placeholder"><h3>PASO 3</h3><h4>Acompañamiento y seguimiento</h4><p>Te brindaremos acompañamiento jurídico, información sobre tus derechos y los pasos a seguir.</p></div></div><p class="placeholder-note">Los detalles de cada paso deben ser validados y completados por el equipo institucional de ATRAHDOM.</p></div></section>`}
function participa(){const cards=[{svg:'defensa',t:'Trabajadora afiliada',d:'Para trabajadoras del hogar, a domicilio y de maquila que quieren organizarse y defender sus derechos.',items:['Acompañamiento y orientación laboral','Formación en derechos y talleres','Participación en asambleas y sindicatos'],cta:'Quiero afiliarme'},{svg:'incidencia',t:'Organización aliada',d:'Para organizaciones, sindicatos y redes que buscan articular acciones con ATRAHDOM.',items:['Alianzas e incidencia conjunta','Espacios de coordinación regional','Campañas y pronunciamientos'],cta:'Proponer alianza'},{svg:'formacion',t:'Voluntariado y colaboración',d:'Para personas que desean aportar tiempo, conocimiento o recursos a la causa.',items:['Apoyo técnico y profesional','Colaboración en investigación','Difusión y solidaridad'],cta:'Quiero colaborar'}];return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Organización y participación</p><h1>Afíliate y participa</h1><p>Hay varias formas de sumarse a ATRAHDOM y a los sindicatos de trabajadoras del hogar.</p></div></section><section class="section"><div class="wrap"><div class="affiliate-grid">${cards.map(c=>`<article class="affiliate-card reveal">${ejeSvg(c.svg)}<h3>${c.t}</h3><p>${c.d}</p><ul class="affiliate-list">${c.items.map(i=>`<li>${i}</li>`).join('')}</ul><a class="btn" href="mailto:coordinacion@atrahdom.org?subject=${encodeURIComponent(c.cta+' — ATRAHDOM')}">${c.cta}</a></article>`).join('')}</div><div class="placeholder affiliate-note"><h3>PLACEHOLDER</h3><p>Los requisitos, las cuotas (si las hubiera) y el proceso formal de afiliación deben ser definidos y validados por el equipo institucional de ATRAHDOM antes de publicarse.</p></div></div></section>`}
function contacto(){const p=state.pages.find(x=>/contact/.test(slugOf(x)));return p?`<section class="page-hero"><div class="wrap"><p class="eyebrow">Información de contacto</p><h1>Contáctanos</h1></div></section><section class="section"><div class="wrap content-layout"><article class="prose">${enhanceContent(contentOf(p))}</article><aside class="sidebar"><h3>Formulario de contacto</h3><div class="placeholder"><h3>PLACEHOLDER</h3><p>El formulario de contacto moderno debe implementarse cuando la organización defina los mecanismos de comunicación y los canales oficiales.</p></div></aside></div></section>`:missing('Información de contacto no disponible.')}
function donation(){const p=state.posts.find(x=>/donacion/i.test(titleOf(x))||/donacion/i.test(slugOf(x)));return p?`<section class="page-hero"><div class="wrap"><p class="eyebrow">Apoya nuestro trabajo</p><h1>Haz una donación</h1></div></section><section class="section"><div class="wrap content-layout"><article class="prose">${enhanceContent(contentOf(p))}</article><aside class="sidebar"><div class="placeholder"><h3>PLACEHOLDER</h3><p>Los datos bancarios y mecanismos actuales de donación deben ser validados con la organización antes de publicarse.</p></div></aside></div></section>`:placeholder('Haz una donación','Apoya el trabajo de ATRAHDOM.')}
function placeholder(title,text){return `<section class="page-hero"><div class="wrap"><p class="eyebrow">Nueva función propuesta</p><h1>${title}</h1><p>${text}</p></div></section><section class="section"><div class="wrap"><div class="placeholder"><h3>PLACEHOLDER DE CONTENIDO</h3><p>Esta sección aún no cuenta con contenido definitivo y requiere definición institucional.</p></div></div></section>`}
function missing(msg){return `<section class="empty wrap"><h1>Contenido no encontrado</h1><p>${msg}</p><a class="btn" href="#/">Volver al inicio</a></section>`}

function findByRoute(path){return [...state.pages,...state.posts,...state.attachments].find(p=>(p.local_route||'').slice(1)===path)||null}
function route(){if(!state.ready)return showLoading();if(state.error){main.innerHTML=`<section class="empty wrap"><h1>No fue posible cargar el contenido</h1><p>${state.error.message}</p></section>`;return}const path=location.hash.slice(1)||'/';let html='';const direct=findByRoute(path);if(direct)html=detail(direct);else if(path==='/')html=home();else if(path==='/quienes-somos')html=institutional();else if(path==='/que-hacemos')html=whatWeDo();else if(path==='/recursos')html=archive('resources');else if(path==='/actualidad')html=archive('posts');else if(path==='/organizaciones')html=unions();else if(path==='/contacto')html=contacto();else if(path==='/ayuda')html=ayuda();else if(path==='/participa')html=participa();else if(path==='/donar')html=donation();else if(path==='/memoria')html=timeline();else if(path==='/publicaciones')html=publications();else if(path==='/privacidad')html=placeholder('Privacidad y tratamiento de datos','Contenido legal pendiente de elaborar y validar.');else if(path.startsWith('/tema/'))html=topic(path.slice(6));else if(path.startsWith('/contenido/')){const id=Number(path.split('/').pop());const p=[...state.posts,...state.pages].find(x=>x.id===id);html=p?detail(p):missing('La publicación solicitada no está disponible.')}else if(path.startsWith('/page/'))html=pageBySlug(path.split('/').pop());else html=pageBySlug(path.slice(1));main.innerHTML=html;window.scrollTo(0,0);if(path==='/recursos')bindArchive('resources');if(path==='/actualidad')bindArchive('posts');initMotion();initGallery();initHero()}

function initHero(){const hero=main.querySelector('.cine-hero');if(!hero)return;if(window.__heroTimer){clearInterval(window.__heroTimer);window.__heroTimer=null}const slides=[...hero.querySelectorAll('.cine-slide')];const video=hero.querySelector('.cine-video');const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(video){const src=video.querySelector('source');video.addEventListener('error',()=>video.classList.add('hidden'),{once:true});if(src)src.addEventListener('error',()=>video.classList.add('hidden'),{once:true});if(reduce){video.removeAttribute('autoplay');try{video.pause()}catch(e){}}else{const pr=video.play&&video.play();if(pr&&pr.catch)pr.catch(()=>{})}}if(!reduce){hero.classList.add('animate');if(slides.length>1){let i=0;window.__heroTimer=setInterval(()=>{slides[i].classList.remove('active');i=(i+1)%slides.length;slides[i].classList.add('active')},6000)}}}
function initGallery(){const imgs=main.querySelectorAll('.original-gallery figure img');if(!imgs.length)return;const d=document.createElement('dialog');d.className='lightbox-dialog';d.innerHTML='<form method="dialog"><button class="dialog-close" aria-label="Cerrar">×</button><img src="" alt=""></form>';document.body.appendChild(d);const img=d.querySelector('img');imgs.forEach(i=>{i.style.cursor='pointer';i.addEventListener('click',()=>{img.src=i.src;img.alt=i.alt;d.showModal()})});d.addEventListener('click',e=>{if(e.target===d)d.close()})}
function initContentCarousels(){main.querySelectorAll('.content-carousel').forEach(carousel=>{const slides=[...carousel.querySelectorAll('.carousel-slide')];if(slides.length<2)return;let index=0;setInterval(()=>{slides[index].classList.remove('active');index=(index+1)%slides.length;slides[index].classList.add('active')},5000)})}
function initMotion(){const els=[...main.querySelectorAll('.reveal')];const counters=[...main.querySelectorAll('.counter[data-count]')];const showAll=()=>{els.forEach(e=>e.classList.add('in'));counters.forEach(c=>c.textContent=c.dataset.count)};if(!('IntersectionObserver' in window))return showAll();const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduce)return showAll();const io=new IntersectionObserver(entries=>entries.forEach(en=>{if(!en.isIntersecting)return;en.target.classList.add('in');io.unobserve(en.target)}),{threshold:.15});els.forEach(e=>io.observe(e));const co=new IntersectionObserver(entries=>entries.forEach(en=>{if(!en.isIntersecting)return;const el=en.target,target=Number(el.dataset.count)||0;co.unobserve(el);const t0=performance.now();const step=now=>{const k=Math.min(1,(now-t0)/600);el.textContent=Math.round(target*(1-Math.pow(1-k,3)));if(k<1)requestAnimationFrame(step)};requestAnimationFrame(step)}),{threshold:.4});counters.forEach(c=>co.observe(c))}

function closeMenus(){$('#primary-menu')?.classList.remove('open');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false');document.querySelectorAll('.nav-group.open').forEach(g=>{g.classList.remove('open');g.querySelector('.nav-trigger')?.setAttribute('aria-expanded','false')})}
function bindGlobal(){document.querySelector('.menu-toggle').onclick=e=>{const n=$('#primary-menu');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',n.classList.contains('open'))};document.querySelectorAll('.nav-trigger').forEach(t=>t.onclick=()=>{const g=t.closest('.nav-group');const willOpen=!g.classList.contains('open');document.querySelectorAll('.nav-group.open').forEach(o=>{if(o!==g){o.classList.remove('open');o.querySelector('.nav-trigger')?.setAttribute('aria-expanded','false')}});g.classList.toggle('open',willOpen);t.setAttribute('aria-expanded',willOpen)});document.querySelectorAll('.primary-menu a').forEach(a=>a.onclick=()=>closeMenus());document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenus()});document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))document.querySelectorAll('.nav-group.open').forEach(g=>{g.classList.remove('open');g.querySelector('.nav-trigger')?.setAttribute('aria-expanded','false')})});const d=$('#search-dialog');$('.search-open').onclick=()=>{d.showModal();setTimeout(()=>$('#site-search').focus(),100)};$('.dialog-close').onclick=()=>d.close();$('#site-search').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q){$('#search-results').innerHTML='';return}const all=[...state.pages,...state.posts];const results=all.filter(p=>`${titleOf(p)} ${strip(contentOf(p))}`.toLowerCase().includes(q));const pageResults=results.filter(p=>p.type==='page').slice(0,8);const postResults=results.filter(p=>p.type!=='page').slice(0,8);let html=`<p class="search-total">${results.length} resultado${results.length!==1?'s':''}</p>`;if(pageResults.length)html+=`<h4 class="search-group">Páginas (${pageResults.length})</h4>${pageResults.map(p=>`<div class="search-hit"><a href="${routeOf(p)}" onclick="document.querySelector('#search-dialog').close()">${highlightText(strip(titleOf(p)),q)}</a></div>`).join('')}`;if(postResults.length)html+=`<h4 class="search-group">Publicaciones (${postResults.length})</h4>${postResults.map(p=>`<div class="search-hit"><a href="${routeOf(p)}" onclick="document.querySelector('#search-dialog').close()">${highlightText(strip(titleOf(p)),q)}</a><div class="meta">${dateOf(p)?safeDate(dateOf(p))+' · ':''}${authorOf(p)}</div></div>`).join('')}`;if(!pageResults.length&&!postResults.length)html='<p class="search-total">Sin resultados.</p>';$('#search-results').innerHTML=html};window.addEventListener('hashchange',route);$('#year').textContent=new Date().getFullYear()}
const baseUnions=unions;const unionExtras=`<article class="card"><div class="card-media"><img src="assets/images/foto0044-a8e024cf26.jpg" alt="SITRADOMSA" loading="lazy" decoding="async"></div><div class="card-body"><div class="meta"><span>Sindicato</span></div><h3>SITRADOMSA.</h3><p>Sindicato de Trabajadoras Domésticas, Similares y a Cuenta Propia.</p><a class="read" href="https://atrahdom.org/#/post/sitradomsa">Leer contenido completo →</a></div></article><article class="card"><div class="card-media"><img src="assets/images/cropped-atrahdom-logo-2019-91a74affa5.png" alt="Nuevo sindicato SITRADOMSA" loading="lazy" decoding="async"></div><div class="card-body"><div class="meta"><span>Sindicato</span></div><h3>NUEVO SINDICATO DE TRABAJADORAS DOMESTICAS, SIMILARES Y A CUENTA PROPIA -SITRADOMSA-</h3><p>Información sobre la organización y fortalecimiento del sindicato de trabajadoras.</p><a class="read" href="https://atrahdom.org/#/post/nuevo-sindicato-de-trabajadoras-domesticas-similares-y-a-cuenta-propia-sitradomsa">Leer contenido completo →</a></div></article>`;unions=()=>baseUnions().replace('<p class="eyebrow">Organización sindical</p>','<p class="eyebrow">Alianzas estratégicas</p>').replace('<h1>SITRADOM y SITRADOMSA</h1>','<h1>Sindicatos</h1>').replace(/<section class="org-card">[\s\S]*?<\/section>/i,'').replace(/<section class="org-card">[\s\S]*?SITRADOMSA[\s\S]*?<\/section>/i,'').replace(/<article class="card">[\s\S]*?Convocator[ií]a en línea al Sector Empleador[\s\S]*?<\/article>/i,'').replace('<div class="grid">','<div class="grid">'+unionExtras);
const renderedUnions=unions;unions=()=>renderedUnions().replace('<div class="meta"><span>Sindicato</span></div><h3>SITRADOMSA.','<div class="meta"><span>Blog</span><span>27 de mayo de 2012</span></div><h3>SITRADOMSA.').replace('<div class="meta"><span>Sindicato</span></div><h3>NUEVO SINDICATO','<div class="meta"><span>Blog</span><span>11 de abril de 2011</span></div><h3>NUEVO SINDICATO').replace('<span>Por Sonicalm</span>','');
const baseDonation=donation;donation=()=>baseDonation().replace(/<section class="media-embed document-embed">[\s\S]*?<\/section>/gi,'').replace(/<aside class="sidebar">[\s\S]*?<\/aside>/i,'');
const renderedDonation=donation;donation=()=>{const box=document.createElement('div');box.innerHTML=renderedDonation();const article=box.querySelector('.prose');if(article)article.innerHTML='<h2>¿Por qué apoyar nuestros programas?</h2><p>Tu contribución ayuda a convertir los derechos en oportunidades reales para mujeres y jóvenes que enfrentan desigualdades en el mundo del trabajo. Al apoyar estos programas, fortaleces el acceso a justicia, la protección frente a la violencia laboral, la generación de conocimiento sobre cambio climático y empleo, la defensa de derechos laborales y el liderazgo de jóvenes defensoras ambientales.</p><p>Cada aporte contribuye a construir una sociedad donde las mujeres puedan trabajar con dignidad, ejercer sus derechos y participar activamente en las decisiones que afectan sus vidas y comunidades. Contribuye al desarrollo de Guatemala mediante una fuerza laboral más protegida, comunidades más resilientes, mayor igualdad y nuevas generaciones comprometidas con un desarrollo justo y sostenible sin dejar a nadie atrás.</p>';return box.innerHTML};
const baseAyuda=ayuda;ayuda=()=>baseAyuda().replace(/ class="step placeholder"/g,' class="step"').replace(/<p class="placeholder-note">[\s\S]*?<\/p>/i,'');
const baseHome=home;home=()=>baseHome().replace(/<section class="section"><div class="wrap"><div class="section-head reveal"><div><p class="eyebrow">Agenda<\/p><h2>Próximas actividades<\/h2>[\s\S]*?<\/section>/i,'');
const homeHeroMessage=home;home=()=>homeHeroMessage().replace('Trabajo como ninguno, derechos como <span class="destacado">cualquier otro</span>.','Las mujeres trabajadoras somos <span class="destacado">generadoras del desarrollo.</span>');
const homeWithoutExplore=home;home=()=>homeWithoutExplore().replace('<a class="btn light" href="#/recursos">Explorar biblioteca</a>','');
const baseEnhanceAxes=enhanceAxesContent;enhanceAxesContent=html=>{const box=document.createElement('div');box.innerHTML=baseEnhanceAxes(html);const heading=[...box.querySelectorAll('h2')].find(h=>h.textContent.trim().toLowerCase()==='ejes transversales');if(!heading)return box.innerHTML;const intro=heading.nextElementSibling;if(intro?.tagName==='P')intro.remove();const entries=[['Desarrollo integral','Partiendo del principio de igualdad y por medio del enfoque de género, apoyamos equitativamente a las poblaciones de mujeres, indígena, niñez, juventud y tercera edad. El desarrollo sostenible no debe dejar a nadie atrás.'],['Medio ambiente','Sin recursos naturales y ambientales, no puede haber vida, por eso nos constituimos en promotoras y defensoras ambientales a nivel nacional.'],['Tecnología','Creemos que la promoción del desarrollo necesita enfoques innovadores, utilizamos la tecnología para ampliar nuestro alcance, facilitar actividades y nuestros servicios de distintas maneras, análogas o digitales.'],['Sistema internacional','Como organización con estado consultivo especial de ECOSOC desde 2021, ATRAHDOM forma parte de la integralidad del sistema de Derechos Humanos.']];const cards=document.createElement('div');cards.className='axes-transverse-grid';entries.forEach((entry,i)=>{const card=document.createElement('article');card.className=`axes-placeholder axes-placeholder-${i+1}`;card.innerHTML=`<h3>${entry[0]}</h3><p>${entry[1]}</p>`;cards.appendChild(card)});heading.insertAdjacentElement('afterend',cards);box.querySelectorAll('p').forEach(p=>{if(p.textContent.trim().startsWith('Nuestra forma de trabajo nos permite'))p.remove()});return box.innerHTML};
const baseDetail=detail;detail=p=>{const html=baseDetail(p);return slugOf(p)==='sindicato-de-trabajadoras-domesticas-de-maquila-nexas-y-conexas-sitradom'?html.replace('<strong>Autoría:</strong><br>Sonicalm','<strong>Autoría:</strong><br>SITRADOM').replace('<span>Por Sonicalm</span>',''):html};
const detailWithoutParticipationMeta=detail;detail=p=>{const html=detailWithoutParticipationMeta(p);return slugOf(p)==='espacios-de-participacion'?html.replace(/(<section class="page-hero">[\s\S]*?<h1>[\s\S]*?<\/h1>)<div class="meta">[\s\S]*?<\/div>/i,'$1'):html};
const detailWithoutParticipationText=detail;detail=p=>{const html=detailWithoutParticipationText(p);if(slugOf(p)!=='espacios-de-participacion')return html;const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('.participation-page .prose .wp-block-columns').forEach(section=>section.remove());return box.innerHTML};
const detailWithParticipationCards=detail;detail=p=>{const html=detailWithParticipationCards(p);if(slugOf(p)!=='espacios-de-participacion')return html;const box=document.createElement('div');box.innerHTML=html;const carousel=box.querySelector('.participation-page .content-carousel');if(!carousel)return html;const entries=[['Mujeres',['Agenda Política de las Mujeres en la Diversidad – APMD','Red Nacional y Mesoamericana de Defensoras de Derechos Humanos','Fundadoras de la Red Guatemalteca por los Cuidados','Coordinadora 8 de marzo','Coordinadora 25 de noviembre']],['Sindical',['Alianza estratégica ATRAHDOM/SITRADOM','Fundadoras de la Federación Unitaria de Trabajadores de Guatemala – FUTG','Fundadoras del Colectivo Independiente Sindical Guatemalteco – CISG','Alianza Sindical con Federación UNSITRAGUA','Miembras y Fundadoras de la Red Centroamericana por el Acceso a la Justicia Laboral de la Población LGTBIQ','Red Nacional por el Acceso a la Justicia Laboral de la Población LGTBIQ','Mecanismo Centroamericano de Mujeres Trabajadoras','Campaña de Ropa Limpia – CCC']],['Gobernanza',['Alianzas interinstitucionales con entidades de Gobierno y Poderes Locales','Fundadoras de la Mesa Multisectorial de Derechos de las Mujeres Trabajadoras Domésticas, del Hogar y de Casa Particular','Coordinación de actividades con las Direcciones Municipales de la Mujer – DMM','Coordinación de actividades con la Secretaría Presidencial de la Mujer – SEPREM.']],['Internacional',['Organización socia de ONU Mujeres a nivel nacional e internacional','Referente de país para la Organización Internacional del Trabajo – OIT, en materia de Mujer Trabajadora y Trabajo Doméstico','Departamento de Información Pública de la ONU','Organización con estado consultativo especial de ECOSOC desde 2021.']],['Ambiental',['Fundadoras de la Alianza Ambientalista para la Preservación de la Laguna Chichoj']]];const grid=document.createElement('div');grid.className='participation-spaces-grid';entries.forEach((entry,i)=>{const card=document.createElement('article');card.className=`participation-space-card participation-space-${i+1}`;card.innerHTML=`<h3>${entry[0]}</h3><ul>${entry[1].map(item=>`<li>${item}</li>`).join('')}</ul>`;grid.appendChild(card)});carousel.insertAdjacentElement('afterend',grid);return box.innerHTML};
const detailFixEnvironmental=detail;detail=p=>slugOf(p)==='espacios-de-participacion'?detailFixEnvironmental(p).replace('Preservación de la Laguna Chichoj</li>','Preservación de la Laguna Chichoj en San Cristóbal Verapaz</li>'):detailFixEnvironmental(p);
const detailOrganizationLayout=detail;detail=p=>{const html=detailOrganizationLayout(p);if(slugOf(p)!=='organizacion')return html;const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('.organization-page .wp-block-social-links').forEach(list=>list.remove());const chart=box.querySelector('.organization-page .organization-chart');const post=[...box.querySelectorAll('.organization-page li,.organization-page p,.organization-page h2,.organization-page h3')].find(el=>el.textContent.trim().toLowerCase().startsWith('post-covid19'));if(chart&&post){const anchor=post.closest('ul')||post;anchor.insertAdjacentElement('afterend',chart)}return box.innerHTML};
const detailOrganizationCards=detail;detail=p=>{const html=detailOrganizationCards(p);if(slugOf(p)!=='organizacion')return html;const box=document.createElement('div');box.innerHTML=html;const prose=box.querySelector('.organization-page .prose');if(!prose)return html;const values=[];[...prose.querySelectorAll('p')].forEach(paragraph=>{const match=paragraph.textContent.trim().match(/^(Visión|Misión|Nuestro objetivo)\s*[:;]\s*(.+)$/i);if(match){values.push([match[1],match[2]]);paragraph.remove()}else if(paragraph.textContent.trim().toLowerCase().startsWith('surge como un espacio necesario'))paragraph.remove()});if(values.length){const grid=document.createElement('div');grid.className='organization-values-grid';values.forEach((value,i)=>{const card=document.createElement('article');card.className=`organization-value-card organization-value-${i+1}`;card.innerHTML=`<h3>${value[0]}</h3><p>${value[1]}</p>`;grid.appendChild(card)});prose.insertBefore(grid,prose.firstElementChild)}return box.innerHTML};
const detailOrganizationStructureCard=detail;detail=p=>{const html=detailOrganizationStructureCard(p);if(slugOf(p)!=='organizacion')return html;const box=document.createElement('div');box.innerHTML=html;const structure=box.querySelector('.organization-page .prose .wp-block-group');if(structure)structure.classList.add('organization-structure-card');return box.innerHTML};
